if ($_SERVER['REQUEST_METHOD']==='POST') {
    require_csrf(); $action=$_POST['action']??'';
    if($action==='login'){ $s=db()->prepare('SELECT * FROM users WHERE email=? AND active=1');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password_hash'])){unset($u['password_hash']);$_SESSION['user']=$u;redirect($u['role']==='admin'?'?page=dashboard':'?page=pos');}$error='Invalid email or password';}
    elseif($action==='save_product'){require_admin();$id=(int)($_POST['id']??0);$image=null;if(!empty($_FILES['image']['tmp_name'])&&is_uploaded_file($_FILES['image']['tmp_name'])){$type=mime_content_type($_FILES['image']['tmp_name']);if(!in_array($type,['image/jpeg','image/png','image/webp'],true))exit('Invalid image type');$image='uploads/'.bin2hex(random_bytes(8)).'.'.(['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$type]);if(!is_dir(__DIR__.'/uploads'))mkdir(__DIR__.'/uploads',0755,true);move_uploaded_file($_FILES['image']['tmp_name'],__DIR__.'/'.$image);}$values=[trim($_POST['name']),trim($_POST['sku']),(int)$_POST['category_id'],(float)$_POST['price'],(int)$_POST['stock'],$_POST['status']];if($id){$sql='UPDATE products SET name=?,sku=?,category_id=?,price=?,stock=?,status=?'.($image?',image=?':'').' WHERE id=?';if($image)$values[]=$image;$values[]=$id;$s=db()->prepare($sql);}else{$s=db()->prepare('INSERT INTO products(name,sku,category_id,price,stock,status,image) VALUES(?,?,?,?,?,?,?)');$values[]=$image;}$s->execute($values);redirect('?page=products');}
    elseif($action==='delete_product'){require_admin();db()->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_POST['id']]);redirect('?page=products');}
    elseif($action==='save_user'){require_admin();$id=(int)($_POST['id']??0);if($id){$sql='UPDATE users SET name=?,email=?,role=?,active=?'.($_POST['password']?' ,password_hash=?':'').' WHERE id=?';$v=[trim($_POST['name']),trim($_POST['email']),$_POST['role'],isset($_POST['active'])?1:0];if($_POST['password'])$v[]=password_hash($_POST['password'],PASSWORD_DEFAULT);$v[]=$id;}else{$sql='INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)';$v=[trim($_POST['name']),trim($_POST['email']),password_hash($_POST['password'],PASSWORD_DEFAULT),$_POST['role']];}db()->prepare($sql)->execute($v);redirect('?page=users');}
    elseif($action==='save_settings'){require_admin();foreach(['gemini_api_key','gemini_model'] as $key){db()->prepare('INSERT INTO settings(`key`,`value`) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)')->execute([$key,$_POST[$key]??'']);}redirect('?page=settings');}
    elseif($action==='test_gemini'){require_admin();$result=gemini_request('Respond with the single word OK.',null);json_response(['ok'=>!isset($result['error']),'message'=>$result['error']??trim($result['text']??'No response')]);}
    elseif($action==='detect'){require_login();if(empty($_FILES['photo']['tmp_name']))json_response(['ok'=>false,'error'=>'Photo is required']);$mime=mime_content_type($_FILES['photo']['tmp_name'])?:'image/jpeg';if(!in_array($mime,['image/jpeg','image/png','image/webp'],true))json_response(['ok'=>false,'error'=>'Please upload a JPG, PNG, or WEBP image']);$image=base64_encode(file_get_contents($_FILES['photo']['tmp_name']));$prompt='Identify retail products in this image. Return ONLY valid JSON array, each item with name and integer quantity. Do not invent prices, SKUs, or products. Example: [{"name":"Coca Cola","quantity":2}]';$result=gemini_request($prompt,$image,$mime);if(isset($result['error']))json_response(['ok'=>false,'error'=>$result['error']]);$text=trim((string)($result['text']??''));$text=preg_replace('/^```(?:json)?\s*|\s*```$/i','',$text);$items=json_decode(trim($text),true);if(!is_array($items))json_response(['ok'=>false,'error'=>'AI returned invalid JSON. Please try another clear product image.']);$out=[];$find=db()->prepare('SELECT id,name,sku,price,stock FROM products WHERE status="active" AND (name LIKE ? OR sku=?) LIMIT 1');foreach($items as $item){$name=trim((string)($item['name']??''));$qty=max(1,(int)($item['quantity']??1));if(!$name)continue;$find->execute(['%'.$name.'%',$name]);$product=$find->fetch();$out[]=['name'=>$name,'quantity'=>$qty,'product'=>$product?:null];}json_response(['ok'=>true,'items'=>$out]);}
    elseif($action==='checkout'){require_login();$items=json_decode($_POST['items']??'[]',true);if(!is_array($items)||!$items)json_response(['ok'=>false,'error'=>'Cart is empty']);$pdo=db();try{$pdo->beginTransaction();$get=$pdo->prepare('SELECT id,name,sku,price,stock FROM products WHERE id=? AND status="active" FOR UPDATE');$lines=[];$subtotal=0;foreach($items as $item){$get->execute([(int)$item['id']]);$p=$get->fetch();$q=(int)$item['quantity'];if(!$p||$q<1||$q>$p['stock'])throw new RuntimeException('Insufficient stock for a product');$line=$p['price']*$q;$subtotal+=$line;$lines[]=[$p,$q,$line];}$method=$_POST['payment_method']??'cash';$total=$subtotal;$paid=(float)$_POST['amount_paid'];if($method==='cash'&&$paid<$total)throw new RuntimeException('Payment is less than total');if($method!=='cash')$paid=$total;$change=max(0,$paid-$total);$receipt='R'.date('YmdHis').random_int(10,99);$pdo->prepare('INSERT INTO orders(receipt_no,cashier_id,subtotal,total,payment_method,amount_paid,change_amount) VALUES(?,?,?,?,?,?,?)')->execute([$receipt,user()['id'],$subtotal,$total,$method,$paid,$change]);$oid=(int)$pdo->lastInsertId();$ins=$pdo->prepare('INSERT INTO order_items(order_id,product_id,product_name,sku,price,quantity,line_total) VALUES(?,?,?,?,?,?,?)');$dec=$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?');foreach($lines as [$p,$q,$line]){$ins->execute([$oid,$p['id'],$p['name'],$p['sku'],$p['price'],$q,$line]);$dec->execute([$q,$p['id']]);}$pdo->commit();json_response(['ok'=>true,'id'=>$oid]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['ok'=>false,'error'=>$e->getMessage()]);}}
}
function gemini_request(string $prompt, ?string $image, string $mime='image/jpeg'): array { global $geminiCaBundle; $key=setting('gemini_api_key');if(!$key)return ['error'=>'Configure a Gemini API key in Settings first'];$model=setting('gemini_model')?:'gemini-3.7-flash';$parts=[['text'=>$prompt]];if($image)$parts[]=['inline_data'=>['mime_type'=>$mime,'data'=>$image]];$payload=json_encode(['contents'=>[['parts'=>$parts]],'generationConfig'=>['temperature'=>0.1]]);$ch=curl_init('https://generativelanguage.googleapis.com/v1beta/models/'.rawurlencode($model).':generateContent?key='.rawurlencode($key));$curlOptions=[CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_POSTFIELDS=>$payload,CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>30];if(is_file($geminiCaBundle))$curlOptions[CURLOPT_CAINFO]=$geminiCaBundle;curl_setopt_array($ch,$curlOptions);$raw=curl_exec($ch);$status=curl_getinfo($ch,CURLINFO_HTTP_CODE);$curlError=curl_error($ch);curl_close($ch);if($curlError)return ['error'=>'Gemini network error: '.$curlError];$data=json_decode($raw?:'',true);if($status===429||isset($data['error']['status'])&&$data['error']['status']==='RESOURCE_EXHAUSTED')return ['error'=>'Gemini 配额已用完，请稍等后再试，或到 Google AI Studio 增加配额。'];if($status>=400||isset($data['error']))return ['error'=>$data['error']['message']??'Gemini request failed (HTTP '.$status.')'];return ['text'=>$data['candidates'][0]['content']['parts'][0]['text']??''];}

